#include <iostream>
#include <algorithm>
#include <numeric>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long la, ra, ta, lb, rb, tb;
    cin >> la >> ra >> ta;
    cin >> lb >> rb >> tb;

    const long long lenA = ra - la + 1;
    const long long lenB = rb - lb + 1;
    const long long g = gcd(ta, tb);

    long long d = (lb - la) % g;
    if (d < 0) d += g;

    auto overlap = [&](long long start) {
        return max(0LL, min(lenA, start + lenB) - max(0LL, start));
    };

    cout << max(overlap(d), overlap(d - g)) << '\n';
    return 0;
}

